/* Identité de l’espace scolaire L’Harmattan — présentation et navigation. */
const carnetLabels={dashboard:'Vue d’ensemble',horaires:'Mon horaire',notes:'Résultats',eleves:'Élèves',enseignants:'Enseignants',cours:'Cours',presences:'Présences',documents:'Documents',budget:'Mes frais scolaires',recus:'Mes reçus',paiements:'Paiements',confirmations:'Suivi des parents',carte:'Ma carte scolaire',annonces:'Vie du collège',profil:'Mon profil'};
function carnetLabel(k){return k==='horaires'&&role==='Administration'?'Horaires des classes':carnetLabels[k];}
function carnetNavItems(){return role==='Élève'?['dashboard','horaires','notes','budget','recus','documents','profil']:role==='Enseignant'?['dashboard','horaires','cours','notes','presences','profil']:['dashboard','eleves','enseignants','horaires','notes','paiements','confirmations','profil'];}
function carnetIcon(k){return k==='dashboard'?'home':k==='profil'?'profile':k==='notes'?'result':k==='budget'?'money':k==='recus'||k==='paiements'?'receipt':k==='horaires'?'calendar':(moduleDefs[k]?.[2]||'book');}
function carnetButton(key){const m=moduleDefs[key]||[carnetLabels[key],'','book','blue'];return `<button type="button" class="carnet-action ${m[3]}" data-tab="${key}"><span class="carnet-action-icon">${ico(carnetIcon(key))}</span><span class="carnet-action-copy"><strong>${carnetLabel(key)||m[0]}</strong><span>${key==='horaires'&&role==='Administration'?'Classes et affectations':m[1]}</span></span><span class="carnet-action-arrow" aria-hidden="true">↗</span></button>`;}
const moneyText=n=>Number(n).toLocaleString('fr-FR',{maximumFractionDigits:2});
dashboard=function(){const pupil=role==='Élève',teacher=role==='Enseignant';const paid=demo.students.reduce((n,s)=>n+s.paid,0),balance=demo.students.reduce((n,s)=>n+s.due-s.paid,0);return `<div class="carnet-intro"><div><span class="carnet-kicker">${pupil?'LE CARNET L’HARMATTAN':teacher?'MON ESPACE ENSEIGNANT':'LE PILOTAGE DU COLLÈGE'}</span><h1>${pupil?'Bonjour, '+esc(student.name)+'.':teacher?'Votre journée au collège.':'Votre collège, en un regard.'}</h1><p>${pupil?'Retrouvez l’essentiel de votre parcours scolaire.':teacher?'Vos cours, vos horaires et le suivi de vos élèves.':'Les élèves, la pédagogie et les paiements, réunis dans votre espace.'}</p></div><span class="carnet-role">${esc(role)}</span></div><div class="carnet-overview"><article class="carnet-feature"><div class="carnet-feature-heading"><span class="carnet-kicker">${pupil?'MON PARCOURS':'MON ORGANISATION'}</span><span class="carnet-feature-mark">${ico(pupil?'book':'calendar')}</span></div><h2>${pupil?esc(student.classe):teacher?'Préparer et transmettre.':'Accompagner chaque parcours.'}</h2><p>${pupil?esc(student.section)+' · Identifiant '+esc(student.id):'Un accès direct à vos outils de travail et aux informations utiles du collège.'}</p><button class="btn carnet-light" data-tab="${pupil?'horaires':teacher?'cours':'eleves'}">${ico(pupil?'calendar':teacher?'book':'people')}${pupil?'Consulter mon horaire':teacher?'Retrouver mes cours':'Consulter les élèves'}<span aria-hidden="true">→</span></button><span class="carnet-values">TRAVAIL <i>·</i> MAÎTRISE <i>·</i> DROITURE</span></article><article class="carnet-account"><div class="carnet-panel-heading"><span class="carnet-kicker">${pupil?'MES FRAIS SCOLAIRES':teacher?'MES REPÈRES':'SUIVI DU COLLÈGE'}</span>${ico(pupil?'money':'result')}</div>${pupil?`<div class="carnet-balance"><span>Solde à payer</span><strong>${moneyText(student.due-student.paid)} <small>USD</small></strong></div><dl><div><dt>Frais attendus</dt><dd>${moneyText(student.due)} USD</dd></div><div><dt>Déjà payé</dt><dd>${moneyText(student.paid)} USD</dd></div></dl><button class="carnet-text-button" data-tab="budget">Voir le détail des frais <span>→</span></button>`:teacher?`<div class="carnet-balance"><span>Séances enregistrées dans la démonstration</span><strong>${demo.slots.length}</strong></div><p>Retrouvez les affectations et les évaluations à renseigner.</p><button class="carnet-text-button" data-tab="horaires">Ouvrir les horaires <span>→</span></button>`:`<div class="carnet-balance"><span>Élèves inscrits</span><strong>${demo.students.length}</strong></div><dl><div><dt>Paiements enregistrés</dt><dd>${moneyText(paid)} USD</dd></div><div><dt>Solde des frais</dt><dd>${moneyText(balance)} USD</dd></div></dl><button class="carnet-text-button" data-tab="paiements">Suivre les paiements <span>→</span></button>`}</article></div><div class="carnet-section-heading"><div><span class="carnet-kicker">${pupil?'AU FIL DES JOURS':'MON QUOTIDIEN'}</span><h2>${pupil?'Ma scolarité.':'Les outils de votre journée.'}</h2></div><p>${pupil?'Apprendre, s’organiser et suivre ses progrès.':'Accéder rapidement à chaque tâche.'}</p></div><div class="carnet-actions">${(pupil?['horaires','cours','notes']:teacher?['horaires','cours','notes']:['eleves','enseignants','horaires','cours','notes','presences']).map(carnetButton).join('')}</div><div class="carnet-section-heading"><div><span class="carnet-kicker">${pupil?'MON DOSSIER':'LE SUIVI'}</span><h2>${pupil?'Mes documents et ma vie scolaire.':teacher?'La vie de votre espace.':'Les familles et l’administration.'}</h2></div></div><div class="carnet-actions secondary-actions">${(pupil?['presences','documents','carte','recus','annonces','profil']:teacher?['presences','documents','annonces','profil']:['paiements','confirmations','documents','annonces','profil']).map(carnetButton).join('')}</div><div class="carnet-demo-note">${ico('check')}<p><b>Vous consultez une démonstration.</b> Les données sont fictives. Les actions sont enregistrées dans ce navigateur ; aucun paiement réel ni message externe n’est effectué.</p></div>`;};
pages.espace=()=>{if(!role){role='Élève';student=demo.students[0];tab='dashboard';}const navs=carnetNavItems();return `<div class="school-app harmattan-shell"><aside class="carnet-sidebar" aria-label="Espace scolaire"><a href="#accueil" class="carnet-brand"><img src="./assets/logo.png" alt="Blason du collège"><span><b>L’HARMATTAN</b><small>Espace scolaire</small></span></a><div class="carnet-sidebar-label">MON ESPACE</div><nav class="carnet-nav" aria-label="Rubriques scolaires">${navs.map(k=>`<button type="button" data-tab="${k}" class="${tab===k?'is-selected':''}" ${tab===k?'aria-current="page"':''}>${ico(carnetIcon(k))}<span>${carnetLabel(k)}</span>${tab===k?'<i aria-hidden="true"></i>':''}</button>`).join('')}</nav><div class="carnet-sidebar-footer"><span>Travail · Maîtrise · Droiture</span><a href="#accueil">← Revenir au site du collège</a><small>Conçu par AMMGROUP Digital</small></div></aside><div class="carnet-main"><header class="carnet-topbar"><div><span>L’Harmattan <i>/</i> ${esc(role)}</span><strong>${carnetLabel(tab)||'Espace scolaire'}</strong></div><div class="carnet-topbar-actions"><label class="carnet-preview-label" for="carnet-role-select">Aperçu<select id="carnet-role-select">${['Élève','Enseignant','Administration'].map(r=>`<option ${role===r?'selected':''}>${r}</option>`).join('')}</select></label><button id="logout" type="button" class="carnet-exit">Quitter ${ico('arrow')}</button></div></header><section class="carnet-body">${tab!=='dashboard'?`<div class="carnet-module-top"><button class="carnet-back" data-tab="dashboard">← Vue d’ensemble</button><span>Données de démonstration</span></div>`:''}<div id="workspace" class="${tab==='dashboard'?'carnet-dashboard':'module-workspace carnet-module'}">${portalContent()}</div><footer class="carnet-bottom-credit"><span>Collège L’Harmattan · Lubumbashi</span><span>AMMGROUP Digital</span></footer></section></div><nav class="carnet-mobile-nav" aria-label="Navigation mobile scolaire">${[['dashboard','Accueil','home'],['horaires','Horaire','calendar'],[role==='Élève'?'budget':role==='Enseignant'?'notes':'paiements',role==='Élève'?'Frais':role==='Enseignant'?'Notes':'Paiements','receipt'],['profil','Profil','profile']].map(([k,l,i])=>`<button type="button" data-tab="${k}" class="${tab===k?'is-selected':''}" ${tab===k?'aria-current="page"':''}>${ico(i)}<span>${l}</span></button>`).join('')}</nav></div>`;};
const bindBeforeDesign=bindPortal;
bindPortal=function(){bindBeforeDesign();const mode=document.getElementById('carnet-role-select');if(mode)mode.onchange=()=>{role=mode.value;if(role==='Élève')student=demo.students[0];tab='dashboard';render();window.scrollTo(0,0);};};
render();
